36	import org.springframework.samples.petclinic.rest.api.OwnersApi;
37	import org.springframework.samples.petclinic.rest.controller.AddressNormalizer;
38	import org.springframework.samples.petclinic.rest.controller.CityRegionResolver;
39	import org.springframework.samples.petclinic.rest.controller.HouseholdResolver;
40	import org.springframework.samples.petclinic.rest.controller.TelephoneNormalizer;
41	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
