1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.controller.CityRegionResolver;
10	import org.springframework.samples.petclinic.rest.controller.TelephoneNormalizer;
11	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
12	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
13	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
14	import org.springframework.samples.petclinic.service.ClinicService;
15	
16	import java.time.LocalDate;
17	import java.time.Period;
18	import java.time.temporal.ChronoUnit;
19	import java.util.Collection;
20	import java.util.List;
21	
22	/**
23	 * Maps Owner & OwnerDto using Mapstruct
24	 */
25	@Mapper(uses = PetMapper.class)
26	public abstract class OwnerMapper {
27	
28	    /** Used to count the members of an owner's household when deriving derived fields. */
29	    @Autowired
30	    protected ClinicService clinicService;
31	
32	    /** Single source of truth for the city-to-region mapping behind an owner's locality. */
33	    @Autowired
34	    protected CityRegionResolver cityRegionResolver;
35	
36	    /** Formats the stored E.164 telephone into its human-readable display form. */
37	    @Autowired
38	    protected TelephoneNormalizer telephoneNormalizer;
39	
40	    @Mapping(target = "displayName",
41	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
42	    @Mapping(target = "initials", expression = "java(initials(owner))")
43	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
44	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
45	    @Mapping(target = "locality", expression = "java(locality(owner))")
46	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
47	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
48	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneNormalizer.toDisplayForm(owner.getTelephone()))")
49	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
50	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
51	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
52	    public abstract OwnerDto toOwnerDto(Owner owner);
53	
54	    /**
55	     * The owner's age band derived from {@code birthDate} relative to the
56	     * {@code registrationDate}: 'MINOR' when under 18, 'ADULT' from 18 to 64
57	     * inclusive and 'SENIOR' at 65 or older. Returns null when either date is
58	     * absent so no band can be computed.
59	     */
60	    OwnerDto.AgeBandEnum ageBand(Owner owner) {
61	        LocalDate birthDate = owner.getBirthDate();
62	        LocalDate registrationDate = owner.getRegistrationDate();
63	        if (birthDate == null || registrationDate == null) {
64	            return null;
65	        }
66	        int age = Period.between(birthDate, registrationDate).getYears();
67	        if (age < 18) {
68	            return OwnerDto.AgeBandEnum.MINOR;
69	        }
70	        if (age < 65) {
71	            return OwnerDto.AgeBandEnum.ADULT;
72	        }
73	        return OwnerDto.AgeBandEnum.SENIOR;
74	    }
75	
76	    /**
77	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits
78	     * contained in the customerCode, or null when no customerCode has been assigned.
79	     */
80	    Integer checkDigit(Owner owner) {
81	        String customerCode = owner.getCustomerCode();
82	        return customerCode == null ? null : luhn(customerCode);
83	    }
84	
85	    /**
86	     * The Luhn check digit (0-9) over the digits contained in {@code s}: from the rightmost
87	     * digit leftward, every second digit is doubled (the rightmost first) with digits over 9
88	     * reduced by 9, and the check digit makes the total a multiple of ten.
89	     */
90	    static int luhn(String s) {
91	        int sum = 0;
92	        boolean doubling = true;
93	        for (int i = s.length() - 1; i >= 0; i--) {
94	            char c = s.charAt(i);
95	            if (c < '0' || c > '9') {
96	                continue;
97	            }
98	            int d = c - '0';
99	            if (doubling) {
100	                d *= 2;
101	                if (d > 9) {
102	                    d -= 9;
103	                }
104	            }
105	            sum += d;
106	            doubling = !doubling;
107	        }
108	        return (10 - (sum % 10)) % 10;
109	    }
110	
111	    /**
112	     * The owner's derived identity key: the normalized telephone, the email (or an empty
113	     * string when absent) and the householdId joined by '|'. This single key is the sole
114	     * basis for duplicate detection on create — two owners are duplicates only when their
115	     * whole identityKey matches, so members of one household with different telephones
116	     * (and hence different keys) are all permitted.
117	     */
118	    public static String identityKey(Owner owner) {
119	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
120	        String email = owner.getEmail() == null ? "" : owner.getEmail();
121	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
122	        return telephone + "|" + email + "|" + householdId;
123	    }
124	
125	    /**
126	     * The owner's preferred contact channel: 'EMAIL' when an email address is
127	     * present, otherwise 'PHONE'.
128	     */
129	    String contactPreference(Owner owner) {
130	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
131	        return hasEmail ? "EMAIL" : "PHONE";
132	    }
133	
134	    /**
135	     * The owner's locality: the REGION component of the customerCode identity (the part before
136	     * the first '-' of {@code '<REGION>-<HASH8>'}). When no customerCode has been assigned this
137	     * falls back to the canonical region derived from the owner via {@link CityRegionResolver},
138	     * preferring the postcode over the city, or 'UNKNOWN' when neither yields a known region.
139	     */
140	    String locality(Owner owner) {
141	        String customerCode = owner.getCustomerCode();
142	        if (customerCode != null) {
143	            int dash = customerCode.indexOf('-');
144	            if (dash >= 0) {
145	                return customerCode.substring(0, dash);
146	            }
147	        }
148	        return cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
149	    }
150	
151	    /**
152	     * The owner's IANA timezone name derived from the owner's {@link #locality(Owner) locality}
153	     * via the fixed region-to-timezone table (NSW -> Australia/Sydney, VIC -> Australia/Melbourne,
154	     * QLD -> Australia/Brisbane). Returns null when the locality is not a region in the table.
155	     */
156	    String timezone(Owner owner) {
157	        return cityRegionResolver.timezoneForRegion(locality(owner));
158	    }
159	
160	    /**
161	     * The owner's membership points: starting at 0, plus 2 when an email address is present,
162	     * plus 1 when namesakeCount is 0, plus 2 for a household of 3 or more members, plus 3 when
163	     * the owner's tenure is more than 365 days.
164	     */
165	    public int membershipPoints(Owner owner) {
166	        int points = 0;
167	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
168	        if (hasEmail) {
169	            points += 2;
170	        }
171	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
172	        if (uniqueName) {
173	            points += 1;
174	        }
175	        if (householdSize(owner) >= 3) {
176	            points += 2;
177	        }
178	        LocalDate registrationDate = owner.getRegistrationDate();
179	        boolean tenured = registrationDate != null
180	            && ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > 365;
181	        if (tenured) {
182	            points += 3;
183	        }
184	        return points;
185	    }
186	
187	    /**
188	     * The owner's numeric membership level from 1 to 4, derived from {@link #membershipPoints}:
189	     * level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points and level 4 for
190	     * 6 or more points.
191	     */
192	    public int membershipLevel(Owner owner) {
193	        int points = membershipPoints(owner);
194	        if (points >= 6) {
195	            return 4;
196	        }
197	        if (points >= 4) {
198	            return 3;
199	        }
200	        if (points >= 2) {
201	            return 2;
202	        }
203	        return 1;
204	    }
205	
206	    /**
207	     * The number of owners belonging to {@code owner}'s household, i.e. those sharing its
208	     * householdId (including the owner itself once persisted). Returns 0 when the owner has no
209	     * household id assigned.
